#!/usr/bin/env bash
#
# Hunt Console — Linux/macOS installer
#
# Self-contained installer: the source package is embedded below as a
# base64-encoded tar.gz payload, so this single file is everything needed
# to install. Run with: bash install-linux.sh [options]
#
# What this does:
#   1. Checks for Python 3.10+
#   2. Extracts the embedded source to a temp directory
#   3. Creates a virtual environment at --prefix (default: ~/.huntconsole)
#   4. Installs the package into it (core tool: zero third-party deps)
#   5. Symlinks the `huntconsole` command into ~/.local/bin
#
# Nothing here requires root. By default, pip installs with normal build
# isolation, which needs internet access the first time to fetch
# setuptools/wheel if not already cached — this is standard `pip install`
# behavior, no different from installing any other Python package from
# source. Use --offline if you are on an air-gapped machine that already
# has setuptools/wheel available system-wide.

set -euo pipefail

PREFIX="${HOME}/.huntconsole"
BIN_DIR="${HOME}/.local/bin"
WITH_CONNECTORS=0
OFFLINE=0

while [[ $# -gt 0 ]]; do
  case "$1" in
    --prefix) PREFIX="$2"; shift 2 ;;
    --with-connectors) WITH_CONNECTORS=1; shift ;;
    --offline) OFFLINE=1; shift ;;
    -h|--help)
      echo "Usage: bash install-linux.sh [--prefix DIR] [--with-connectors] [--offline]"
      echo "  --prefix DIR         install location (default: ~/.huntconsole)"
      echo "  --with-connectors    also install requests/msal for live alert pulls"
      echo "  --offline            skip pip build isolation (requires setuptools/wheel"
      echo "                       already available system-wide); for air-gapped hosts"
      exit 0
      ;;
    *) echo "Unknown argument: $1" >&2; exit 1 ;;
  esac
done

echo "== Hunt Console installer =="

PYTHON_BIN=""
for candidate in python3.13 python3.12 python3.11 python3.10 python3; do
  if command -v "$candidate" >/dev/null 2>&1; then
    ver=$("$candidate" -c 'import sys; print(f"{sys.version_info[0]}.{sys.version_info[1]}")' 2>/dev/null) || continue
    major="${ver%%.*}"; minor="${ver##*.}"
    if [[ "$major" -eq 3 && "$minor" -ge 10 ]]; then
      PYTHON_BIN="$candidate"
      break
    fi
  fi
done

if [[ -z "$PYTHON_BIN" ]]; then
  echo "ERROR: Python 3.10+ not found on PATH. Install Python 3.10 or newer and re-run." >&2
  exit 1
fi
echo "Using $($PYTHON_BIN --version) at $(command -v "$PYTHON_BIN")"

WORKDIR="$(mktemp -d)"
trap 'rm -rf "$WORKDIR"' EXIT

echo "Extracting embedded package..."
PAYLOAD_LINE=$(grep -n '^__PAYLOAD_BELOW__$' "$0" | head -1 | cut -d: -f1)
if [[ -z "$PAYLOAD_LINE" ]]; then
  echo "ERROR: embedded payload marker not found — this installer file may be corrupted or truncated." >&2
  exit 1
fi
tail -n +$((PAYLOAD_LINE + 1)) "$0" | base64 -d | tar xz -C "$WORKDIR"

echo "Creating virtual environment at $PREFIX ..."
"$PYTHON_BIN" -m venv --system-site-packages --clear "$PREFIX"

echo "Installing Hunt Console..."
if [[ "$OFFLINE" -eq 1 ]]; then
  "$PREFIX/bin/pip" install --quiet --no-build-isolation "$WORKDIR"
else
  if ! "$PREFIX/bin/pip" install --quiet "$WORKDIR"; then
    echo "" >&2
    echo "ERROR: pip install failed. If this machine has no internet access," >&2
    echo "re-run with --offline (requires setuptools/wheel already available system-wide)." >&2
    exit 1
  fi
fi

if [[ "$WITH_CONNECTORS" -eq 1 ]]; then
  "$PREFIX/bin/pip" install --quiet "requests>=2.31" "msal>=1.28" || \
    echo "WARNING: could not install requests/msal (no network?) — core tool still works, live 'alert' command will not."
fi

mkdir -p "$BIN_DIR"
ln -sf "$PREFIX/bin/huntconsole" "$BIN_DIR/huntconsole"

echo ""
echo "== Installed =="
echo "  huntconsole -> $PREFIX/bin/huntconsole"
echo "  symlinked to $BIN_DIR/huntconsole"
if [[ ":$PATH:" != *":$BIN_DIR:"* ]]; then
  echo ""
  echo "  $BIN_DIR is not on your PATH. Add this to your shell profile:"
  echo "    export PATH=\"$BIN_DIR:\$PATH\""
fi
echo ""
echo "Try it:"
echo "  huntconsole --help"
echo ""
exit 0

